export const createBallAnnotationSessionBodyDevelopmentPackageSessionIdOneRegExp =
  new RegExp("^[a-z0-9][a-z0-9._-]{0,119}$");
export const createBallAnnotationSessionBodyDevelopmentPackageSha256OneRegExp =
  new RegExp("^[0-9a-f]{64}$");

export const CreateBallAnnotationSessionBody = zod.object({
  data_role: zod.enum(["development", "check"]),
  development_probe_job_ids: zod
    .array(
      zod
        .string()
        .regex(createBallAnnotationSessionBodyDevelopmentProbeJobIdsItemRegExp),
    )
    .min(1)
    .max(createBallAnnotationSessionBodyDevelopmentProbeJobIdsMax),
  locked_profile_id: zod
    .string()
    .regex(createBallAnnotationSessionBodyLockedProfileIdRegExp),
  target_frame_count: zod
    .union([
      zod
        .number()
        .min(createBallAnnotationSessionBodyTargetFrameCountOneMin)
        .max(createBallAnnotationSessionBodyTargetFrameCountOneMax),
      zod.null(),
    ])
    .optional(),
  sampling_profile_id: zod.literal("tiny_ball_temporal_groups_v1"),
  metric_profile_id: zod.literal("tiny_ball_feasibility_metric_v1"),
  operator_id: zod
    .string()
    .regex(createBallAnnotationSessionBodyOperatorIdRegExp),
  strata_applicability: zod.object({
    scale: zod
      .array(
        zod.object({
          stratum: zod.enum(["near", "mid", "far"]),
          status: zod.enum(["applicable", "not_applicable"]),
          evidence_note: zod
            .string()
            .min(
              createBallAnnotationSessionBodyStrataApplicabilityScaleItemEvidenceNoteMin,
            )
            .max(
              createBallAnnotationSessionBodyStrataApplicabilityScaleItemEvidenceNoteMax,
            ),
        }),
      )
      .min(createBallAnnotationSessionBodyStrataApplicabilityScaleMin)
      .max(createBallAnnotationSessionBodyStrataApplicabilityScaleMax),
    lighting: zod
      .array(
        zod.object({
          stratum: zod.enum([
            "bright_sun",
            "shadow",
            "backlight",
            "twilight",
            "artificial_light",
          ]),
          status: zod.enum(["applicable", "not_applicable"]),
          evidence_note: zod
            .string()
            .min(
              createBallAnnotationSessionBodyStrataApplicabilityLightingItemEvidenceNoteMin,
            )
            .max(
              createBallAnnotationSessionBodyStrataApplicabilityLightingItemEvidenceNoteMax,
            ),
          quota: zod
            .number()
            .min(
              createBallAnnotationSessionBodyStrataApplicabilityLightingItemQuotaMin,
            )
            .max(
              createBallAnnotationSessionBodyStrataApplicabilityLightingItemQuotaMax,
            )
            .describe(
              "Development\/not-applicable uses 0; every applicable check lighting stratum requires at least 3.",
            ),
          frame_intervals: zod
            .array(
              zod.object({
                start_frame: zod
                  .number()
                  .min(
                    createBallAnnotationSessionBodyStrataApplicabilityLightingItemFrameIntervalsItemStartFrameMin,
                  ),
                end_frame: zod
                  .number()
                  .min(
                    createBallAnnotationSessionBodyStrataApplicabilityLightingItemFrameIntervalsItemEndFrameMin,
                  ),
              }),
            )
            .max(
              createBallAnnotationSessionBodyStrataApplicabilityLightingItemFrameIntervalsMax,
            ),
        }),
      )
      .min(createBallAnnotationSessionBodyStrataApplicabilityLightingMin)
      .max(createBallAnnotationSessionBodyStrataApplicabilityLightingMax),
  }),
  retry_from_session_id: zod
    .union([
      zod
        .string()
        .regex(createBallAnnotationSessionBodyRetryFromSessionIdOneRegExp),
      zod.null(),
    ])
    .optional(),
  development_package_session_id: zod
    .union([
      zod
        .string()
        .regex(
          createBallAnnotationSessionBodyDevelopmentPackageSessionIdOneRegExp,
        ),
      zod.null(),
    ])
    .optional(),
  development_package_sha256: zod
    .union([
      zod
        .string()
        .regex(
          createBallAnnotationSessionBodyDevelopmentPackageSha256OneRegExp,
        ),
      zod.null(),
    ])
    .optional(),
});

